package mesh
import("sort";"strings";"time")
type Path struct{NextHop string `json:"next_hop"`;Metric uint32 `json:"metric"`;Hops int `json:"hops"`}
func SelectPaths(paths []Path,maxPaths int)[]Path{if maxPaths<=0||len(paths)==0{return nil};out:=make([]Path,0,len(paths));for _,p:=range paths{p.NextHop=strings.TrimSpace(p.NextHop);if p.NextHop==""||len(p.NextHop)>256||p.Hops<0{continue};out=append(out,p)};sort.SliceStable(out,func(i,j int)bool{if out[i].Metric!=out[j].Metric{return out[i].Metric<out[j].Metric};if out[i].Hops!=out[j].Hops{return out[i].Hops<out[j].Hops};return out[i].NextHop<out[j].NextHop});dedup:=out[:0];seen:=make(map[string]struct{},len(out));for _,p:=range out{if _,ok:=seen[p.NextHop];ok{continue};seen[p.NextHop]=struct{}{};dedup=append(dedup,p)};if len(dedup)>maxPaths{dedup=dedup[:maxPaths]};return dedup}
func RemoveUnhealthy(paths []Path,healthyNextHops map[string]bool)[]Path{if len(paths)==0{return nil};out:=make([]Path,0,len(paths));for _,p:=range paths{p.NextHop=strings.TrimSpace(p.NextHop);if p.NextHop!=""&&len(p.NextHop)<=256&&p.Hops>=0&&healthyNextHops[p.NextHop]{out=append(out,p)}};return out}
type FailoverDecision struct{CurrentLink string `json:"current_link"`;CandidateLink string `json:"candidate_link"`;Reason string `json:"reason"`;Score uint32 `json:"score"`;GeneratedAt time.Time `json:"generated_at"`}
func ChooseFailover(current string,links []Link,now time.Time,maxAge time.Duration)(FailoverDecision,bool){current=strings.TrimSpace(current);if len(current)>256||maxAge<=0{return FailoverDecision{},false};if now.IsZero(){now=time.Now().UTC()}else{now=now.UTC()};var best Link;found:=false;for _,l:=range links{l.ID=strings.TrimSpace(l.ID);if l.ID==""||len(l.ID)>256||l.ID==current||l.State!=LinkUp||l.UpdatedAt.IsZero()||now.Before(l.UpdatedAt)||now.Sub(l.UpdatedAt)>maxAge{continue};if !found||l.Metric<best.Metric||(l.Metric==best.Metric&&l.ID<best.ID){best,found=l,true}};if !found{return FailoverDecision{},false};return FailoverDecision{CurrentLink:current,CandidateLink:best.ID,Reason:"healthy alternative with lower path metric",Score:best.Metric,GeneratedAt:now},true}
